import React, { useMemo } from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
  Easing,
  random,
} from '../remotionShim';
// Start Google Fonts Loader
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map((f) => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(`link[href*="${font.replace(/\s+/g, "+")}"]`)
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
// End Google Fonts Loader



export type StickyNoteProps = Record<string, any>;

const StickyNote: React.FC<StickyNoteProps> = ({
  backgroundColor = "#f3f4f6",
  transparentBackground = false,
  durationInSeconds = 6,
  noteColor = "#fef08a",
  inkColor = "#1e293b",
  textContent = "Don't forget to smile today! :)",
  noteSize = 500,
  noteRotation = -3,
}) => {
  useFontLoader(["Caveat", "Inter"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // --- Helpers ---
  const bgColor = transparentBackground
    ? `${backgroundColor}00`
    : backgroundColor;
  
  // Split text into lines for individual handling
  const lines = useMemo(() => textContent.split("\n"), [textContent]);
  const totalChars = textContent.length;

  // --- Animation Timing ---
  const entranceDuration = 35; // Frames for the note to drop in
  const writingDelay = 45; // Start writing after note settles
  
  // 1. Note Entry Animation (Drop + Spring Settle)
  const dropSpring = spring({
    frame,
    fps,
    config: {
      damping: 12,
      stiffness: 100,
      mass: 1,
    },
  });

  const rotationSpring = spring({
    frame: frame - 10, // Slight delay on rotation for natural feel
    fps,
    config: {
      damping: 15,
      stiffness: 60,
    },
  });

  // Calculate entrance values
  const startY = -height / 2 - noteSize;
  const targetY = 0; // Relative to center
  
  const translateY = interpolate(dropSpring, [0, 1], [startY, targetY]);
  
  // Subtle float/hover effect after it lands
  const float = Math.sin(frame / 40) * 5; 

  // Final transform composition
  const currentRotation = interpolate(
    rotationSpring,
    [0, 1],
    [random(123) * 20 - 10, noteRotation] // Start random, end at user prop
  );

  // 2. Handwriting Animation Logic
  // We want to write character by character, but pausing at newlines
  // This logic calculates which characters should be visible based on the frame
  
  const charsPerSecond = 15; // Speed of writing
  const writingProgress = Math.max(0, frame - writingDelay);
  const totalWritingDuration = (totalChars / charsPerSecond) * fps; 
  
  // Determine how many characters to show
  const visibleCharCount = interpolate(
    writingProgress,
    [0, totalChars * (fps / charsPerSecond)],
    [0, totalChars],
    { extrapolateRight: "clamp", extrapolateLeft: "clamp" }
  );

  // --- Render Helpers ---
  
  // Function to render text with the "typewriter" cursor logic applied to lines
  let charAccumulator = 0;
  
  const renderLines = () => {
    return lines.map((line, lineIndex) => {
      const lineLength = line.length;
      const lineStartIndex = charAccumulator;
      const lineEndIndex = lineStartIndex + lineLength;
      
      // Update accumulator for next line (plus 1 for the newline char effectively)
      charAccumulator += lineLength; 

      // Determine how much of this line is visible
      const charsToShowInLine = Math.max(0, Math.min(lineLength, Math.floor(visibleCharCount - lineStartIndex)));
      const visibleString = line.slice(0, charsToShowInLine);

      // Add a slight "ink bleed" opacity ramp for the last visible character
      // This is a micro-optimization for visual smoothness
      const opacity = 1; 

      return (
        <div
          key={lineIndex}
          style={{
            display: "block",
            whiteSpace: "pre-wrap",
            height: "1.5em", // Fixed line height to prevent layout jumps
            marginBottom: "0.2em",
          }}
        >
          {visibleString}
        </div>
      );
    });
  };

  // Paper texture overlay (using SVG noise pattern encoded as data URI for stability)
  const paperTexture = `url("data:image/svg+xml,%3Csvg viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='noiseFilter'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.65' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23noiseFilter)' opacity='0.08'/%3E%3C/svg%3E")`;

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        justifyContent: "center",
        alignItems: "center",
        fontFamily: "Inter, sans-serif",
      }}
    >
      {/* Sticky Note Container */}
      <div
        style={{
          width: noteSize,
          height: noteSize, // Square sticky note
          backgroundColor: noteColor,
          transform: `translateY(${translateY + float}px) rotate(${currentRotation}deg)`,
          boxShadow: `10px 10px 30px rgba(0,0,0,0.15), 0px 0px 5px rgba(0,0,0,0.05)`,
          position: "relative",
          display: "flex",
          flexDirection: "column",
          padding: noteSize * 0.1, // 10% padding
          boxSizing: "border-box",
          overflow: "hidden", // Clip content to note
          // Slight curl effect using border-radius
          borderBottomRightRadius: `${noteSize * 0.15}px 60px`,
          borderBottomLeftRadius: "2px",
          borderTopLeftRadius: "2px",
          borderTopRightRadius: "2px",
        }}
      >
        {/* Paper Texture Overlay */}
        <div 
          style={{
            position: 'absolute',
            top: 0,
            left: 0,
            width: '100%',
            height: '100%',
            backgroundImage: paperTexture,
            mixBlendMode: 'multiply',
            pointerEvents: 'none',
          }}
        />
        
        {/* Adhesive Strip Gradient (Subtle at top) */}
        <div
            style={{
                position: 'absolute',
                top: 0,
                left: 0,
                width: '100%',
                height: '15%',
                background: 'linear-gradient(to bottom, rgba(0,0,0,0.03), transparent)',
                pointerEvents: 'none',
            }}
        />

        {/* Text Container */}
        <div
          style={{
            fontFamily: "Caveat, cursive",
            color: inkColor,
            fontSize: noteSize * 0.12, // Responsive font size
            lineHeight: 1.4,
            width: "100%",
            height: "100%",
            zIndex: 1,
            position: "relative",
            fontWeight: 700, // Make it look like a marker
            opacity: 0.9, // Ink isn't perfectly opaque
          }}
        >
          {renderLines()}
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default StickyNote;